import Foundation

/// Bridges the Rust core's `SecretCallbacks` (generated by UniFFI) to the Keychain.
/// All real logic lives in `SecretVault` / `SystemKeychainBackend` (Shared/).
final class AppSecretCallbacks: SecretCallbacks, @unchecked Sendable {
    private let vault: SecretVault

    init(vault: SecretVault) {
        self.vault = vault
    }

    static func makeDefault() -> AppSecretCallbacks {
        let backend = SystemKeychainBackend(
            service: AppConstants.keychainService,
            accessGroup: AppConstants.keychainAccessGroup
        )
        return AppSecretCallbacks(vault: SecretVault(backend: backend))
    }

    func put(id: String, value: String) -> Bool { vault.put(id: id, value: value) }
    func get(id: String) -> String? { vault.get(id: id) }
    func delete(id: String) -> Bool { vault.delete(id: id) }
}
